def populate_active_transfer_batch_guards(apps, schema_editor):
    PendingTransferRequest = apps.get_model('api', 'PendingTransferRequest')
    PendingTransferBatchGuard = apps.get_model('api', 'PendingTransferBatchGuard')

    for transfer in PendingTransferRequest.objects.filter(status='PENDING').iterator():
        batch_numbers = {str(transfer.batch_number or '').strip().replace(' ', '').upper()}
        batch_numbers.update(
            str((line or {}).get('batch_number') or (line or {}).get('batchNumber') or '')
            .strip()
            .replace(' ', '')
            .upper()
            for line in (transfer.lines or [])
        )
        source_warehouse = str(transfer.from_warehouse or '').strip().upper()
        transfer_stage = str(transfer.transfer_stage or '').strip()
        for batch_number in batch_numbers:
            if not batch_number or not source_warehouse or not transfer_stage:
                continue
            PendingTransferBatchGuard.objects.get_or_create(
                normalized_batch_number=batch_number,
                normalized_from_warehouse=source_warehouse,
                transfer_stage=transfer_stage,
                defaults={'transfer_id': transfer.id},
            )


def clear_active_transfer_batch_guards(apps, schema_editor):
    apps.get_model('api', 'PendingTransferBatchGuard').objects.all().delete()


